def _task_window_business_events(
    events: Sequence[Mapping[str, Any]],
    dynamic_ids: Mapping[str, str],
) -> tuple[list[tuple[Any, ...]], list[dict[str, Any]]]:
    """Return every durable business event between the first and last required events.

    The brief fixes no per-post order, so the window is bounded by whichever
    required events come first and last, not by fixed first/last events.
    """
    expected = set(_expected_events())
    required_indices = [
        index
        for index, event in enumerate(events)
        if _project_event(event, dynamic_ids) in expected
    ]
    first_index = required_indices[0] if required_indices else None
    last_index = required_indices[-1] if required_indices else None
    if first_index is None or last_index is None or last_index < first_index:
        return [], []

    durable_types = {
        "post_created",
        "comment_created",
        "post_like_toggled",
        "post_bookmark_toggled",
        "post_repost_toggled",
    }
    projected: list[tuple[Any, ...]] = []
    unexpected: list[dict[str, Any]] = []
    for event in events[first_index : last_index + 1]:
        event_type = str(event.get("type") or "")
        if event_type not in durable_types:
            continue
        item = _project_event(event, dynamic_ids)
        if item is None:
            unexpected.append(dict(event))
            projected.append((
                "UNEXPECTED",
                event_type,
                str(event.get("postId") or ""),
                str(event.get("text") or ""),
                event.get("active"),
            ))
        else:
            projected.append(item)
    return projected, unexpected


class OpenTwitterTransitSignalEngagement483271Evaluator(BaseEvaluator):
    """Evaluate exact durable OpenTwitter state without changing the simulator."""

    @classmethod
    def evaluate_state(cls, state: Mapping[str, Any]) -> EvalResult:
        checks: list[dict[str, Any]] = []
        posts = _rows(state.get("posts"))
        comments = state.get("comments") if isinstance(state.get("comments"), Mapping) else {}
        dynamic_ids: dict[str, str] = {}

        created_group_names = {
            "transit pulse": "transit_pulse",
            "sensor trend": "sensor_trend",
            "route update": "route_update",
        }
        for text, reply in CREATED_POSTS.items():
            matches = [
                row
                for row in posts
                if str(row.get("authorHandle") or "") == AUTHOR_HANDLE
                and str(row.get("text") or "") == text
            ]
            post_id = str(matches[0].get("id") or "") if len(matches) == 1 else ""
            reply_matches = _comments_for(comments, post_id, reply) if post_id else []
            if post_id:
                dynamic_ids[text] = post_id
            actual = {
                "post_count": len(matches),
                "post_id": post_id,
                "reply_count": len(reply_matches),
                "reply_text": reply_matches[0].get("text") if len(reply_matches) == 1 else None,
            }
            checks.append(_check(
                name=f"created_post_{text.replace(' ', '_')}_exact",
                value_contract_id=f"created.{text}",
                steps=STEP_GROUPS[created_group_names[text]],
                expected={"post_count": 1, "reply_count": 1, "reply_text": reply},
                actual=actual,
                evidence={"matching_posts": matches, "matching_replies": reply_matches},
                passed=len(matches) == 1 and len(reply_matches) == 1,
            ))

        allowed_dynamic_post_ids = set(dynamic_ids.values())
        unexpected_authored_posts = [
            row
            for row in posts
            if str(row.get("authorHandle") or "") == AUTHOR_HANDLE
            and str(row.get("id") or "") not in allowed_dynamic_post_ids
            and re.fullmatch(r"p-(?:\d{4}|alex-\d+)", str(row.get("id") or "")) is None
        ]
        checks.append(_check(
            name="created_post_inventory_exact",
            value_contract_id="created.inventory",
            steps=list(range(25, 58)),
            expected={"dynamic_post_ids": sorted(allowed_dynamic_post_ids), "unexpected": []},
            actual={
                "dynamic_post_ids": sorted(allowed_dynamic_post_ids),
                "unexpected": unexpected_authored_posts,
            },
            evidence={"unexpected_authored_posts": unexpected_authored_posts},
            passed=len(dynamic_ids) == len(CREATED_POSTS) and not unexpected_authored_posts,
        ))

        for post_id, spec in SEED_POSTS.items():
            matches = [row for row in posts if str(row.get("id") or "") == post_id]
            expected_comment = spec["comment"]
            reply_matches = (
                _comments_for(comments, post_id, str(expected_comment))
                if expected_comment is not None
                else []
            )
            actual = {
                "post_count": len(matches),
                "authorHandle": str(matches[0].get("authorHandle") or "") if len(matches) == 1 else "",
                "text": str(matches[0].get("text") or "") if len(matches) == 1 else "",
            }
            expected = {
                "post_count": 1,
                "authorHandle": spec["authorHandle"],
                "text": spec["text"],
            }
            if expected_comment is not None:
                actual.update({
                    "reply_count": len(reply_matches),
                    "reply_text": reply_matches[0].get("text") if len(reply_matches) == 1 else None,
                })
                expected.update({"reply_count": 1, "reply_text": expected_comment})
            checks.append(_check(
                name=f"seed_post_{post_id}_exact",
                value_contract_id=f"seed.{post_id}",
                steps=STEP_GROUPS[str(spec["group"])],
                expected=expected,
                actual=actual,
                evidence={"matching_posts": matches, "matching_replies": reply_matches},
                passed=actual == expected,
            ))

        user_states = state.get("userStateByHandle") if isinstance(state.get("userStateByHandle"), Mapping) else {}
        user_state = user_states.get(AUTHOR_HANDLE) if isinstance(user_states.get(AUTHOR_HANDLE), Mapping) else {}
        dynamic_id_set = set(dynamic_ids.values())
        for field, static_expected in EXPECTED_STATIC_ENGAGEMENTS.items():
            expected_set = set(static_expected) | dynamic_id_set
            actual_values = [
                str(item)
                for item in user_state.get(field, [])
                if str(item)
            ] if isinstance(user_state.get(field), list) else []
            actual_set = set(actual_values)
            duplicates = sorted({item for item in actual_values if actual_values.count(item) > 1})
            checks.append(_check(
                name=f"{field}_exact",
                value_contract_id=f"engagement.{field}",
                steps=list(range(1, 79)),
                expected=sorted(expected_set),
                actual={"ids": sorted(actual_set), "duplicates": duplicates},
                evidence={
                    "user_handle": AUTHOR_HANDLE,
                    "field": field,
                    "raw_values": actual_values,
                },
                passed=(
                    len(dynamic_id_set) == len(CREATED_POSTS)
                    and actual_set == expected_set
                    and not duplicates
                ),
            ))

        session = state.get("session") if isinstance(state.get("session"), Mapping) else {}
        session_user = session.get("user") if isinstance(session.get("user"), Mapping) else {}
        session_actual = {
            "loggedIn": session.get("loggedIn") is True,
            "handle": str(session_user.get("handle") or ""),
        }
        checks.append(_check(
            name="session_exact",
            value_contract_id="session.alex_logged_in",
            steps=list(range(1, 79)),
            expected={"loggedIn": True, "handle": AUTHOR_HANDLE},
            actual=session_actual,
            evidence={"session": dict(session)},
            passed=session_actual == {"loggedIn": True, "handle": AUTHOR_HANDLE},
        ))

        events = _rows(state.get("evaluationEvents"))
        projected, unexpected_events = _task_window_business_events(events, dynamic_ids)
        expected_projection = _expected_events()
        creation_order = [item[1] for item in projected if item[0] == "post_created"]
        creation_order_ok = creation_order == list(REQUIRED_CREATION_ORDER)
        checks.append(_check(
            name="durable_events_and_required_order",
            value_contract_id="events.required_durable_set_and_creation_order",
            steps=list(range(1, 79)),
            expected={
                "events": [list(item) for item in expected_projection],
                "post_created_order": list(REQUIRED_CREATION_ORDER),
            },
            actual={
                "events": [list(item) for item in projected],
                "missing": [list(item) for item in (Counter(expected_projection) - Counter(projected)).elements()],
                "extra": [list(item) for item in (Counter(projected) - Counter(expected_projection)).elements()],
                "post_created_order": creation_order,
            },
            evidence={"events": events, "unexpected_business_events": unexpected_events},
            passed=Counter(projected) == Counter(expected_projection) and creation_order_ok,
        ))

        task_comment_events = {
            (
                str(event.get("postId") or ""),
                str(event.get("text") or ""),
                str(event.get("commentId") or ""),
            )
            for event in events
            if str(event.get("type") or "") == "comment_created"
            and _project_event(event, dynamic_ids) is not None
        }
        unexpected_authored_comments = []
        for post_id, rows in comments.items():
            for row in _rows(rows):
                if str(row.get("authorHandle") or "") != AUTHOR_HANDLE:
                    continue
                comment_id = str(row.get("id") or "")
                if re.fullmatch(r"c-\d{4}", comment_id):
                    continue
                identity = (str(post_id), str(row.get("text") or ""), comment_id)
                if identity not in task_comment_events:
                    unexpected_authored_comments.append({"post_id": str(post_id), **row})
        checks.append(_check(
            name="created_comment_inventory_exact",
            value_contract_id="comments.inventory",
            steps=list(range(1, 77)),
            expected={"unexpected": []},
            actual={"unexpected": unexpected_authored_comments},
            evidence={
                "task_comment_events": sorted(task_comment_events),
                "unexpected_authored_comments": unexpected_authored_comments,
            },
            passed=not unexpected_authored_comments,
        ))

        failures = [check["name"] for check in checks if not check["passed"]]
        metadata = {
            "read_only": True,
            "source_state_mode": "human_completed_eval_only",
            "ruleset_sha256": RULESET_SHA256,
            "instruction_sha256": INSTRUCTION_SHA256,
            "checks": checks,
            "observed": {
                "applications": [{"bundle_id": DEFAULT_BUNDLE_ID}],
                "dynamic_post_ids": dynamic_ids,
                "liked_post_ids": sorted(_text_set(user_state.get("likedPostIds"))),
                "bookmarked_post_ids": sorted(_text_set(user_state.get("bookmarkedPostIds"))),
                "reposted_post_ids": sorted(_text_set(user_state.get("repostedPostIds"))),
                "event_count": len(events),
            },
            "failures": failures,
        }
        return EvalResult(
            status=EvalStatus.PASS if not failures else EvalStatus.FAIL,
            message=(
                "OpenTwitter transit-signal workflow matches every exact checkpoint"
                if not failures
                else "OpenTwitter transit-signal workflow failed exact checkpoints: "
                + ", ".join(failures)
            ),
            metadata=metadata,
        )

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        binding_errors = []
        if str(params.get("expected_instruction_sha256") or "") != INSTRUCTION_SHA256:
            binding_errors.append("instruction_sha256")
        if str(params.get("expected_ruleset_sha256") or "") != RULESET_SHA256:
            binding_errors.append("ruleset_sha256")
        if str(params.get("source_simulator_name") or "") != SOURCE_SIMULATOR_NAME:
            binding_errors.append("source_simulator_name")
        if str(params.get("ios_device_profile") or "") != IOS_DEVICE_PROFILE:
            binding_errors.append("ios_device_profile")
        if binding_errors:
            return EvalResult(
                status=EvalStatus.ERROR,
                message="OpenTwitter evaluator binding mismatch: " + ", ".join(binding_errors),
                metadata={
                    "read_only": True,
                    "source_state_mode": "human_completed_eval_only",
                    "ruleset_sha256": RULESET_SHA256,
                    "instruction_sha256": INSTRUCTION_SHA256,
                    "binding_errors": binding_errors,
                },
            )

        bundle_id = str(params.get("bundle_id") or DEFAULT_BUNDLE_ID)
        db_path = str(params.get("db_path") or "").strip()
        seed_data_path = str(params.get("seed_data_path") or "").strip()
        data_container_path = str(params.get("data_container_path") or "").strip()
        try:
            if db_path:
                store = OpenTwitterStore(
                    db_path,
                    bundle_id=bundle_id,
                    seed_data_path=seed_data_path or None,
                    data_container_path=data_container_path or None,
                )
            else:
                udid = str(params.get("udid") or "").strip()
                if not udid:
                    return EvalResult(
                        status=EvalStatus.ERROR,
                        message="OpenTwitter evaluator requires the runner-bound simulator UDID",
                        metadata={"read_only": True, "ruleset_sha256": RULESET_SHA256},
                    )
                store = OpenTwitterStore.from_simulator(udid, bundle_id=bundle_id)
            return self.evaluate_state(store.read_state())
        except Exception as exc:
            return EvalResult(
                status=EvalStatus.ERROR,
                message=f"Failed to read OpenTwitter state: {type(exc).__name__}: {exc}",
                metadata={
                    "read_only": True,
                    "source_state_mode": "human_completed_eval_only",
                    "ruleset_sha256": RULESET_SHA256,
                    "instruction_sha256": INSTRUCTION_SHA256,
                    "exception_type": type(exc).__name__,
                },
            )
